$root = Split-Path $PSScriptRoot -Parent
$url='http://127.0.0.1:8765/api/state'; try { $state=Invoke-RestMethod $url; $account=Invoke-RestMethod 'http://127.0.0.1:8765/api/account'; $port=Get-NetTCPConnection -State Listen -LocalPort 8765; [pscustomobject]@{ PID=$port.OwningProcess; Transport=$state.transport_state; LastWsPayload=$state.last_ws_payload; LiveFeeds=@($state.feed_quality.PSObject.Properties.Value|Where-Object status -in 'LIVE_WS','LIVE_REST_FALLBACK').Count; Account=$account.auth; RegularOrders=$account.regular_orders; AlgoOrders=$account.algo_orders; TotalOrders=$account.total_orders; SnapshotAt=$account.snapshot_at } | ConvertTo-Json -Depth 4 } catch { Write-Output 'Binance Sniper is not reachable on port 8765.'; exit 1 }
